import type { Rule } from "../rules/types.js";

const cell = (text: string): string => text.replace(/\|/g, "\\|");

/** Generated by `womm rules docs`, and checked by a test so it can't go stale. */
export function renderRulesDoc(rules: Rule[]): string {
  const rows = rules.map(
    (rule) =>
      `| \`${rule.id}\` | ${cell(rule.title)} | ${cell(rule.fix)} | [Source](${rule.source}) |`,
  );
  return [
    "# Known causes",
    "",
    "Generated by `womm rules docs`. Edit the files in `rules/`, not this page.",
    "",
    `There are ${rules.length} rules.`,
    "",
    "| Rule | What it means | Fix | Evidence |",
    "| --- | --- | --- | --- |",
    ...rows,
    "",
  ].join("\n");
}
